-- MiPay SME ecosystem - baseline schema (Flyway V1, generated from JPA entities
-- with org.hibernate.dialect.PostgreSQLDialect via jakarta schema-generation; 
-- currency NAD; N+1-safe DTO-only API sits above this schema; postgres profile only.

create table account_mappings (created_at timestamp(6) with time zone, balance_account_id varchar(36) not null, connector_id varchar(36), id varchar(36) not null, merchant_id varchar(36) not null, issuer_account_ref varchar(255) not null, legal_holder varchar(255) not null, primary key (id));
create table advance_repayments (amount numeric(18,2) not null, collection_date date, eligible_sales_base numeric(18,2), created_at timestamp(6) with time zone, advance_id varchar(36) not null, id varchar(36) not null, merchant_id varchar(36) not null, source_payment_id varchar(36), primary key (id));
create table advances (principal_amount numeric(18,2) not null, repayment_rate numeric(5,4) not null, requested_amount numeric(18,2) not null, total_repayment numeric(18,2) not null, closed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, funded_at timestamp(6) with time zone, assessment_id varchar(36), id varchar(36) not null, lender_id varchar(36) not null, merchant_id varchar(36) not null, purpose varchar(255), status varchar(255) not null check (status in ('OFFERED','ACCEPTED','FUNDED','REPAYING','CLOSED','DEFAULTED')), primary key (id));
create table aml_alerts (closed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, entity_id varchar(36) not null, id varchar(36) not null, reference_id varchar(36), alert_type varchar(255) not null, details varchar(1000), entity_type varchar(255) not null, status varchar(255) not null check (status in ('OPEN','INVESTIGATING','CLOSED')), primary key (id));
create table api_clients (rate_limit_tps integer, created_at timestamp(6) with time zone, last_rotated_at timestamp(6) with time zone, id varchar(36) not null, client_id varchar(255) not null unique, client_name varchar(255) not null, scopes varchar(1000), status varchar(255) not null check (status in ('ACTIVE','REVOKED')), primary key (id));
create table arrears_cases (days_past_due integer, opened_at timestamp(6) with time zone, resolved_at timestamp(6) with time zone, advance_id varchar(36) not null, id varchar(36) not null, lender_id varchar(36) not null, status varchar(255) check (status in ('OPEN','RESOLVED')), primary key (id));
create table audit_logs (simulated boolean default false, created_at timestamp(6) with time zone, actor_id varchar(36), entity_id varchar(36), id varchar(36) not null, action varchar(255) not null, actor_role varchar(255), after_hash varchar(255), before_hash varchar(255), entity_type varchar(255), ip_address varchar(255), meta varchar(1000), primary key (id));
create table backups (completed_at timestamp(6) with time zone, started_at timestamp(6) with time zone, id varchar(36) not null, backup_type varchar(255) not null check (backup_type in ('FULL','INCREMENTAL')), status varchar(255) not null check (status in ('SUCCESS','FAILED')), primary key (id));
create table balance_accounts (created_at timestamp(6) with time zone, id varchar(36) not null, owner_id varchar(36) not null, currency varchar(255) not null, issuer_account_ref varchar(255), legal_holder varchar(255), owner_type varchar(255) not null check (owner_type in ('MERCHANT','SUPPLIER')), status varchar(255) check (status in ('ACTIVE','FROZEN','CLOSED')), primary key (id), unique (owner_type, owner_id));
create table balance_holds (amount numeric(18,2) not null, created_at timestamp(6) with time zone, expires_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, reason varchar(255) not null, reference varchar(255), status varchar(255) not null check (status in ('ACTIVE','CONVERTED','RELEASED','EXPIRED')), primary key (id));
create table card_terminals (created_at timestamp(6) with time zone, last_seen_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, status varchar(255) not null check (status in ('ACTIVE','INACTIVE')), terminal_id varchar(255) not null, primary key (id));
create table complaints (created_at timestamp(6) with time zone, resolved_at timestamp(6) with time zone, assigned_to varchar(36), id varchar(36) not null, merchant_id varchar(36), supplier_id varchar(36), category varchar(255), description text, resolution varchar(1000), status varchar(255) not null check (status in ('OPEN','IN_PROGRESS','RESOLVED','CLOSED')), primary key (id));
create table consent_withdrawals (created_at timestamp(6) with time zone, withdrawn_at timestamp(6) with time zone, consent_id varchar(36) not null, id varchar(36) not null, reason varchar(255), primary key (id));
create table credit_assessments (avg_monthly_net_receipts numeric(18,2), eligible_total numeric(18,2), eligible_trading_days integer, score numeric(5,0), window_end date, window_start date, created_at timestamp(6) with time zone, consent_id varchar(36), id varchar(36) not null, lender_id varchar(36) not null, merchant_id varchar(36) not null, decision varchar(255) not null check (decision in ('APPROVED','DECLINED','MANUAL_REVIEW')), reason_codes varchar(500), primary key (id));
create table credit_consents (granted_at timestamp(6) with time zone, withdrawn_at timestamp(6) with time zone, id varchar(36) not null, lender_id varchar(36) not null, merchant_id varchar(36) not null, data_fields varchar(1000), purpose varchar(255) not null, retention_period varchar(255), status varchar(255) not null check (status in ('ACTIVE','WITHDRAWN')), primary key (id));
create table deployments (deployed_at timestamp(6) with time zone, deployed_by varchar(36), id varchar(36) not null, environment varchar(255) not null, notes varchar(500), status varchar(255) not null check (status in ('SUCCESS','FAILED','ROLLED_BACK')), version varchar(255) not null, primary key (id));
create table devices_sessions (created_at timestamp(6) with time zone, expires_at timestamp(6) with time zone, id varchar(36) not null, user_id varchar(36) not null, device_fingerprint varchar(255), mfa_method varchar(255), token_hash varchar(255), primary key (id));
create table disputes (created_at timestamp(6) with time zone, resolved_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, payment_id varchar(36) not null, details varchar(1000), reason varchar(255), status varchar(255) not null check (status in ('OPEN','WON','LOST')), primary key (id));
create table dsar_requests (completed_at timestamp(6) with time zone, requested_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, requested_by varchar(36), payload_ref varchar(500), status varchar(255) not null check (status in ('RECEIVED','PROCESSING','COMPLETED')), primary key (id));
create table eligibility_rules (effective_from date, enabled boolean default true, approved_by varchar(36), id varchar(36) not null, definition varchar(500), rule_code varchar(255) not null unique, primary key (id));
create table fee_reports (amount_billed numeric(18,2), amount_collected numeric(18,2), report_date date not null, created_at timestamp(6) with time zone, id varchar(36) not null, fee_code varchar(255) not null, primary key (id));
create table fee_tariffs (effective_from date not null, effective_to date, external_cost numeric(8,4), tariff_value numeric(8,4) not null, approved_by varchar(36), id varchar(36) not null, code varchar(255) not null unique, cost_basis varchar(255) not null check (cost_basis in ('CONTRACTED','PROVISION','UNQUOTED')), note varchar(300), rate_type varchar(255) not null check (rate_type in ('PERCENTAGE','FIXED')), primary key (id));
create table fee_transactions (amount numeric(18,2) not null, created_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, fee_code varchar(255) not null, reference varchar(255) not null, status varchar(255) not null check (status in ('APPLIED','REVERSED')), primary key (id), unique (fee_code, reference));
create table incidents (acknowledged_late boolean, acknowledged_at timestamp(6) with time zone, created_at timestamp(6) with time zone, resolved_at timestamp(6) with time zone, id varchar(36) not null, description text, severity varchar(255) not null check (severity in ('CRITICAL','HIGH','MEDIUM','LOW')), status varchar(255) not null check (status in ('OPEN','MITIGATED','RESOLVED')), title varchar(255) not null, primary key (id));
create table integration_connectors (health_latency_ms integer, created_at timestamp(6) with time zone, last_health_check timestamp(6) with time zone, id varchar(36) not null, auth_type varchar(255) check (auth_type in ('OAUTH2','API_KEY','MTLS')), base_url varchar(255), capabilities varchar(2000), connector_type varchar(255) not null check (connector_type in ('BANK_ISSUER','LENDER','IPS','CARD','QR','KYC','NOTIFICATION')), credentials_ref varchar(255), environment varchar(255) not null check (environment in ('SANDBOX','UAT','PRODUCTION')), name varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','DISABLED','FAILED')), primary key (id));
create table inventory_items (current_stock numeric(18,2), reorder_level numeric(18,2), id varchar(36) not null, merchant_id varchar(36) not null, name varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','RETIRED')), unit varchar(255), primary key (id));
create table invoice_payments (amount numeric(18,2) not null, confirmed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, hold_id varchar(36), id varchar(36) not null, invoice_id varchar(36) not null, merchant_id varchar(36) not null, supplier_id varchar(36) not null, bank_reference varchar(255), idempotency_key varchar(255) not null unique, payment_route varchar(255) not null check (payment_route in ('BOOK_TRANSFER','EFT')), status varchar(255) not null check (status in ('HELD','PROCESSING','CONFIRMED','FAILED','TIMED_OUT')), primary key (id));
create table invoices (amount numeric(18,2) not null, issued_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, order_id varchar(36), supplier_id varchar(36) not null, currency varchar(255) not null, invoice_number varchar(255) not null, status varchar(255) not null check (status in ('ISSUED','PARTIALLY_PAID','PAID','CANCELLED')), unique_reference varchar(255) not null unique, primary key (id));
create table issuer_balance_ledger (amount numeric(18,2) not null, created_at timestamp(6) with time zone, balance_account_id varchar(36) not null, id varchar(36) not null, owner_id varchar(36) not null, currency varchar(255) not null, entry_type varchar(255) not null check (entry_type in ('CREDIT','DEBIT')), idempotency_key varchar(255) not null unique, issuer_reference varchar(255), owner_type varchar(255) not null check (owner_type in ('MERCHANT','SUPPLIER')), primary key (id));
create table khata_accounts (created_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, customer_name varchar(255) not null, customer_phone varchar(255), status varchar(255) not null check (status in ('ACTIVE','SETTLED','WRITTEN_OFF')), primary key (id));
create table khata_entries (amount numeric(18,2) not null, due_date date, created_at timestamp(6) with time zone, settled_at timestamp(6) with time zone, id varchar(36) not null, khata_id varchar(36) not null, entry_type varchar(255) not null check (entry_type in ('CHARGE','PAYMENT')), primary key (id));
create table kyc_checks (checked_at timestamp(6) with time zone, entity_id varchar(36) not null, id varchar(36) not null, check_type varchar(255) not null check (check_type in ('IDENTITY','SANCTIONS','ADVERSE_MEDIA')), details varchar(500), entity_type varchar(255) not null, result varchar(255) not null check (result in ('PASS','FAIL','MANUAL_REVIEW')), primary key (id));
create table lender_credit_ledger (amount numeric(18,2) not null, balance_after numeric(18,2) not null, created_at timestamp(6) with time zone, advance_id varchar(36) not null, id varchar(36) not null, lender_id varchar(36) not null, merchant_id varchar(36) not null, entry_type varchar(255) not null check (entry_type in ('CREDIT','DEBIT')), primary key (id));
create table lenders (collection_rate numeric(5,4), lender_limit numeric(18,2), max_daily_deduction numeric(18,2), service_fee_rate numeric(5,4), id varchar(36) not null, user_id varchar(36), licence_ref varchar(255), name varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','SUSPENDED')), primary key (id));
create table limit_profiles (advance_cap numeric(18,2), arrears_trigger_pct numeric(5,4), daily_debit_cap numeric(18,2), max_balance numeric(18,2), withdrawal_cap numeric(18,2), id varchar(36) not null, merchant_id varchar(36), primary key (id));
create table merchant_subledger (amount numeric(18,2) not null, created_at timestamp(6) with time zone, balance_account_id varchar(36) not null, id varchar(36) not null, issuer_ledger_id varchar(36), owner_id varchar(36) not null, source_ref_id varchar(36), currency varchar(255) not null, entry_type varchar(255) not null check (entry_type in ('CREDIT','DEBIT')), owner_type varchar(255) not null check (owner_type in ('MERCHANT','SUPPLIER')), source varchar(255) not null check (source in ('PAYMENT','CARD','ADVANCE','REPAYMENT','WITHDRAWAL','REFUND','FEE','SUPPLIER_PAYMENT','OTHER')), status varchar(255) not null check (status in ('PENDING_CONFIRMATION','CONFIRMED','REVERSED')), primary key (id));
create table merchants (approved_at timestamp(6) with time zone, created_at timestamp(6) with time zone, approved_by varchar(36), id varchar(36) not null, user_id varchar(36) not null, approval_status varchar(255) check (approval_status in ('PENDING','APPROVED','SUSPENDED')), business_name varchar(255) not null, business_type varchar(255), kyc_status varchar(255) check (kyc_status in ('PENDING','VERIFIED','REJECTED')), owner_id_number varchar(255), owner_name varchar(255), owner_phone varchar(255), registration_number varchar(255), primary key (id));
create table monitoring_metrics (metric_value numeric(18,4), recorded_at timestamp(6) with time zone, id varchar(36) not null, metric_name varchar(255) not null, primary key (id));
create table notification_templates (id varchar(36) not null, body varchar(500) not null, channel varchar(255) not null check (channel in ('SMS','WHATSAPP','SPEAKER','EMAIL','PUSH')), event_code varchar(255) not null, locale varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','DRAFT')), primary key (id));
create table order_items (quantity numeric(18,2) not null, unit_price numeric(18,2) not null, catalogue_item_id varchar(36), id varchar(36) not null, inventory_item_id varchar(36), order_id varchar(36) not null, product_name varchar(255) not null, unit varchar(255), primary key (id));
create table orders (created_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, supplier_id varchar(36) not null, status varchar(255) not null check (status in ('DRAFT','SUBMITTED','INVOICED','FULFILLED','CANCELLED')), primary key (id));
create table payment_events (simulated boolean default true, created_at timestamp(6) with time zone, id varchar(36) not null, payment_id varchar(36) not null, event_type varchar(255) not null check (event_type in ('INITIATED','CALLBACK','CONFIRMED','TIMEOUT','FAILED','REFUNDED','DUPLICATE_IGNORED')), meta varchar(500), payload_hash varchar(255), primary key (id), unique (payment_id, event_type, payload_hash));
create table payments (amount numeric(18,2) not null, item_quantity numeric(18,2), confirmed_at timestamp(6) with time zone, created_at timestamp(6) with time zone, id varchar(36) not null, item_id varchar(36), merchant_id varchar(36) not null, channel varchar(255) not null check (channel in ('QR','SHORT_CODE','CARD')), currency varchar(255) not null, idempotency_key varchar(255) not null unique, payer_ref varchar(255), status varchar(255) not null check (status in ('INITIATED','PENDING','CONFIRMED','FAILED','REFUNDED')), primary key (id));
create table portfolio_snapshots (arrears_amount numeric(18,2), outstanding_principal numeric(18,2), snapshot_date date, created_at timestamp(6) with time zone, id varchar(36) not null, lender_id varchar(36) not null, primary key (id));
create table qr_codes (created_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, qr_payload varchar(255) not null, status varchar(255) not null check (status in ('ACTIVE','ROTATED','REVOKED')), primary key (id));
create table reconciliation_breaks (amount numeric(18,2), created_at timestamp(6) with time zone, resolved_at timestamp(6) with time zone, id varchar(36) not null, resolved_by varchar(36), run_id varchar(36) not null, break_type varchar(255) not null check (break_type in ('MISSING_CREDIT','DUPLICATE_DEBIT','STALE_HOLD','ORPHAN_PAYMENT')), description varchar(255), reference varchar(255), status varchar(255) not null check (status in ('OPEN','RESOLVED')), primary key (id));
create table reconciliation_rules (tolerance numeric(18,2), id varchar(36) not null, break_category varchar(255), match_key varchar(255), name varchar(255) not null, schedule_cron varchar(255), status varchar(255) not null check (status in ('ACTIVE','ROTATED','REVOKED')), primary key (id));
create table reconciliation_runs (breaks_count integer, credit_ledger_total numeric(18,2), issuer_total numeric(18,2), run_date date not null, subledger_total numeric(18,2), created_at timestamp(6) with time zone, id varchar(36) not null, status varchar(255) not null check (status in ('MATCHED','BREAKS_FOUND')), primary key (id));
create table refunds (amount numeric(18,2) not null, created_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, payment_id varchar(36) not null, reason varchar(255), status varchar(255) not null check (status in ('REQUESTED','PROCESSED','FAILED')), primary key (id));
create table reorder_rules (order_quantity numeric(18,2), reorder_level numeric(18,2), id varchar(36) not null, item_id varchar(36) not null, merchant_id varchar(36) not null, preferred_supplier_id varchar(36), primary key (id));
create table restore_tests (ok boolean default true, rpo_achieved_minutes integer, rto_achieved_minutes integer, tested_at timestamp(6) with time zone, backup_id varchar(36) not null, id varchar(36) not null, tested_by varchar(36), primary key (id));
create table sar_reports (created_at timestamp(6) with time zone, submitted_at timestamp(6) with time zone, alert_id varchar(36), id varchar(36) not null, reported_by varchar(36), details text, reference varchar(255), status varchar(255) not null check (status in ('DRAFT','SUBMITTED','ACKNOWLEDGED')), primary key (id));
create table security_settings (updated_at timestamp(6) with time zone, id varchar(36) not null, updated_by varchar(36), setting_key varchar(255) not null unique, setting_value varchar(255), primary key (id));
create table settlements (settlement_date date not null, total_amount numeric(18,2), created_at timestamp(6) with time zone, id varchar(36) not null, cycle varchar(255), status varchar(255) not null check (status in ('PENDING','SETTLED')), primary key (id));
create table short_codes (created_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, short_code varchar(255) not null unique, status varchar(255) not null check (status in ('ACTIVE','ROTATED','REVOKED')), primary key (id));
create table simulation_scenarios (enabled boolean default true, is_labelled boolean default true not null, id varchar(36) not null, action varchar(255) not null check (action in ('CALLBACK','TIMEOUT','FAILURE','DUPLICATE','REFUND','FUND_ADVANCE')), connector_type varchar(255) check (connector_type in ('BANK_ISSUER','LENDER','IPS','CARD','QR','KYC','NOTIFICATION')), description varchar(500), name varchar(255) not null, payload varchar(1000), primary key (id));
create table statements (period_end date not null, period_start date not null, generated_at timestamp(6) with time zone, generated_by varchar(36), id varchar(36) not null, owner_id varchar(36) not null, file_ref varchar(255), owner_type varchar(255) not null, primary key (id));
create table stock_alerts (resolved boolean default false, created_at timestamp(6) with time zone, id varchar(36) not null, item_id varchar(36) not null, merchant_id varchar(36) not null, alert_type varchar(255) not null check (alert_type in ('LOW_STOCK','OUT_OF_STOCK')), primary key (id));
create table stock_movements (quantity numeric(18,2) not null, created_at timestamp(6) with time zone, id varchar(36) not null, item_id varchar(36) not null, movement_type varchar(255) not null check (movement_type in ('SALE','DELIVERY','ADJUSTMENT','WASTE')), reference varchar(255), primary key (id));
create table supplier_bank_accounts (approved_at timestamp(6) with time zone, created_at timestamp(6) with time zone, approved_by varchar(36), id varchar(36) not null, requested_by varchar(36), supplier_id varchar(36) not null, account_holder varchar(255) not null, account_number varchar(255) not null, bank_name varchar(255) not null, request_note varchar(255), status varchar(255) check (status in ('PENDING_APPROVAL','APPROVED','REJECTED','REVOKED')), primary key (id));
create table supplier_catalogue_items (unit_price numeric(18,2), created_at timestamp(6) with time zone, id varchar(36) not null, supplier_id varchar(36) not null, product_name varchar(255) not null, status varchar(255) check (status in ('PENDING_APPROVAL','APPROVED','RETIRED')), unit varchar(255), primary key (id));
create table suppliers (created_at timestamp(6) with time zone, id varchar(36) not null, user_id varchar(36) not null, approval_status varchar(255) check (approval_status in ('PENDING','APPROVED','SUSPENDED')), business_name varchar(255) not null, owner_name varchar(255), owner_phone varchar(255), registration_number varchar(255), primary key (id));
create table suspensions (lifted_at timestamp(6) with time zone, suspended_at timestamp(6) with time zone, entity_id varchar(36) not null, id varchar(36) not null, suspended_by varchar(36), entity_type varchar(255) not null check (entity_type in ('MERCHANT','SUPPLIER')), reason varchar(255) not null, primary key (id));
create table tab_entries (amount numeric(18,2) not null, created_at timestamp(6) with time zone, id varchar(36) not null, tab_id varchar(36) not null, description varchar(255), primary key (id));
create table tabs (due_date date, total_amount numeric(18,2) not null, created_at timestamp(6) with time zone, settled_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, customer_name varchar(255) not null, customer_phone varchar(255), status varchar(255) not null check (status in ('OPEN','PAID','OVERDUE','WRITTEN_OFF')), primary key (id));
create table tenants (created_at timestamp(6) with time zone, id varchar(36) not null, name varchar(255) not null, status varchar(255) check (status in ('ACTIVE','SUSPENDED')), type varchar(255) check (type in ('TPTS','MINDLABS','ISSUER','LENDER','SUPPLIER')), primary key (id));
create table test_data_sets (labelled_synthetic boolean default true, record_count integer, created_at timestamp(6) with time zone, id varchar(36) not null, description varchar(1000), name varchar(255) not null, primary key (id));
create table users (created_at timestamp(6) with time zone, id varchar(36) not null, email varchar(255), name varchar(255), password_hash varchar(255), phone varchar(255) not null unique, role varchar(255) not null check (role in ('MERCHANT','SUPPLIER','LENDER','TPTS_OPS','MINDLABS_ADMIN')), status varchar(255) check (status in ('PENDING','ACTIVE','SUSPENDED')), primary key (id));
create table vintage_analysis (cohort_month date, loss_rate numeric(5,4), losses numeric(18,2), originations numeric(18,2), id varchar(36) not null, lender_id varchar(36) not null, primary key (id));
create table withdrawals (amount numeric(18,2) not null, processed_at timestamp(6) with time zone, requested_at timestamp(6) with time zone, id varchar(36) not null, merchant_id varchar(36) not null, bank_reference varchar(255), status varchar(255) not null check (status in ('REQUESTED','APPROVED','PAID','FAILED')), primary key (id));
